True def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [[0] * w for _ in range(h)]
    walls = [r for r, row in enumerate(grid) if row and all(v == 2 for v in row)]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 2:
                out[r][c] = 2
            elif v == 4 and r + 1 < h:
                out[r + 1][c] = 4
    if walls:
        wall = walls[0]
        above = [(r, c) for r in range(wall) for c in range(w) if grid[r][c] == 4]
        if above:
            nearest = max(r for r, c in above)
            for r, c in above:
                if r == nearest:
                    vertex = r + 1
                    for rr in range(vertex + 1):
                        delta = vertex - rr
                        for cc in (c - delta, c + delta):
                            if 0 <= cc < w:
                                out[rr][cc] = 4
    return out
